import openpyxl
wb = openpyxl.load_workbook('input.xlsx', data_only=False)
ws = wb['Sales Schedule']
from openpyxl.utils import get_column_letter
# columns U(21) to AJ(36), rows 14-40
for r in range(14, 41):
    vals = []
    for c in range(21, 37):
        v = ws.cell(row=r, column=c).value
        if v is not None:
            vals.append(f"{get_column_letter(c)}{r}={v!r}")
    if vals:
        print(" | ".join(vals)[:800])

